import java.io.*
import java.util.*

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextInt()
    val m = st.nextLong()
    val a = IntArray(n)
    val b = IntArray(n)
    val stA = StringTokenizer(br.readLine())
    for (i in 0 until n) a[i] = stA.nextInt()
    val stB = StringTokenizer(br.readLine())
    for (i in 0 until n) b[i] = stB.nextInt()

    val total = m * n
    val half = total / 2

    // DP[i][j] = min cost to process i brackets with balance j
    val INF = Long.MAX_VALUE / 2
    val dp = Array(2) { Array(half + 1) { LongArray(half + 1) { INF } } }
    dp[0][0][0] = 0

    for (i in 0 until total) {
        val curr = i % 2
        val next = 1 - curr
        for (j in 0..half) {
            for (k in 0..half) {
                if (dp[curr][j][k] == INF) continue
                val cost = dp[curr][j][k]
                // Place '('
                if (j < half) {
                    val newCost = cost + a[i % n]
                    if (newCost < dp[next][j + 1][k]) {
                        dp[next][j + 1][k] = newCost
                    }
                }
                // Place ')'
                if (k < j) {
                    val newCost = cost + b[i % n]
                    if (newCost < dp[next][j][k + 1]) {
                        dp[next][j][k + 1] = newCost
                    }
                }
            }
        }
        // Reset current layer
        for (j in 0..half) {
            for (k in 0..half) {
                dp[curr][j][k] = INF
            }
        }
    }

    println(dp[total % 2][half][half])
}
