    val b = br.readLine().split(" ").map { it.toInt() }

    val total = n * m
    val half = total / 2

    // dp[i][j] = min cost to process first i brackets with balance j
    // balance cannot exceed half (since we need half closing brackets)
    val INF = Long.MAX_VALUE / 2
    val dp = Array(total + 1) { LongArray(half + 1) { INF } }
    dp[0][0] = 0

    for (i in 0 until total) {
        val idx = i % n
        for (j in 0..half) {
            if (dp[i][j] == INF) continue
            // Place '('
            if (j + 1 <= half) {
                dp[i + 1][j + 1] = minOf(dp[i + 1][j + 1], dp[i][j] + a[idx])
            }
            // Place ')'
            if (j > 0) {
                dp[i + 1][j - 1] = minOf(dp[i + 1][j - 1], dp[i][j] + b[idx])
            }
        }
    }

    println(dp[total][0])
