                dp[i + 1][j + 1] = minOf(dp[i + 1][j + 1], dp[i][j] + ai)
            }
            // Place close bracket
            if (j > 0) {
                dp[i + 1][j - 1] = minOf(dp[i + 1][j - 1], dp[i][j] + bi)
            }
        }
    }

    println(dp[total][0])
