import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val a = br.readLine().split(" ").map { it.toInt() }
    val b = br.readLine().split(" ").map { it.toInt() }

    val total = n * m
    val half = total / 2

    // dp[i][balance] = min cost to reach position i with current balance
    val dp = Array(total + 1) { LongArray(n + 1) { Long.MAX_VALUE / 2 } }
    dp[0][0] = 0

    for (i in 0 until total) {
        val mod = i % n
        for (balance in 0..n) {
            if (dp[i][balance] == Long.MAX_VALUE / 2) continue
            // Place '('
            if (balance < n) {
                val newCost = dp[i][balance] + a[mod]
                if (newCost < dp[i + 1][balance + 1]) {
                    dp[i + 1][balance + 1] = newCost
                }
            }
            // Place ')'
            if (balance > 0) {
                val newCost = dp[i][balance] + b[mod]
                if (newCost < dp[i + 1][balance - 1]) {
                    dp[i + 1][balance - 1] = newCost
                }
            }
        }
    }

    println(dp[total][0])
}
