import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val a = br.readLine().split(" ").map { it.toInt() }
    val b = br.readLine().split(" ").map { it.toInt() }

    val total = n * m
    val half = total / 2

    val dp = Array(half + 1) { LongArray(n + 1) { Long.MAX_VALUE } }
    dp[0][0] = 0

    for (i in 0 until total) {
        val next = Array(half + 1) { LongArray(n + 1) { Long.MAX_VALUE } }
        val ai = a[i % n]
        val bi = b[i % n]
        for (open in 0..half) {
            for (balance in 0..n) {
                if (dp[open][balance] == Long.MAX_VALUE) continue
                val cost = dp[open][balance]
                if (open < half) {
                    val newBalance = balance + 1
                    if (newBalance <= n) {
                        val newCost = cost + ai
                        if (newCost < next[open + 1][newBalance]) {
                            next[open + 1][newBalance] = newCost
                        }
                    }
                }
                if (balance > 0) {
                    val newBalance = balance - 1
                    val newCost = cost + bi
                    if (newCost < next[open][newBalance]) {
                        next[open][newBalance] = newCost
                    }
                }
            }
        }
        dp.forEachIndexed { idx, arr -> arr.forEachIndexed { bIdx, _ -> arr[bIdx] = next[idx][bIdx] } }
    }

    println(dp[half][0])
}
