import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val a = br.readLine().split(" ").map { it.toInt() }
    val b = br.readLine().split(" ").map { it.toInt() }

    val total = n * m
    val half = total / 2

    // dp[i][balance] = minimum cost to process first i brackets with current balance
    // balance ranges from 0 to half (since we can't have more than half open brackets)
    val INF = Long.MAX_VALUE / 2
    val dp = Array(total + 1) { LongArray(half + 1) { INF } }
    dp[0][0] = 0

    for (i in 0 until total) {
        val ai = a[i % n]
        val bi = b[i % n]
        for (j in 0..half) {
            if (dp[i][j] == INF) continue
            // Place open bracket
            if (j + 1 <= half) {
                val cost = dp[i][j] + ai
                if (cost < dp[i + 1][j + 1]) {
                    dp[i + 1][j + 1] = cost
                }
            }
            // Place close bracket
            if (j > 0) {
                val cost = dp[i][j] + bi
                if (cost < dp[i + 1][j - 1]) {
                    dp[i + 1][j - 1] = cost
                }
            }
        }
    }

    println(dp[total][0])
}
