        val next = Array(half + 1) { LongArray(n + 1) { Long.MAX_VALUE } }
        for (j in 0..half) {
            for (k in 0..n) {
                if (dp[j][k] == Long.MAX_VALUE) continue
                // Place '('
                if (j < half) {
                    val nj = j + 1
                    val nk = if (k < n) k + 1 else n
                    val cost = dp[j][k] + ai
                    if (cost < next[nj][nk]) {
                        next[nj][nk] = cost
                    }
                }
                // Place ')'
                if (k > 0) {
                    val nj = j
                    val nk = k - 1
                    val cost = dp[j][k] + bi
                    if (cost < next[nj][nk]) {
                        next[nj][nk] = cost
                    }
                }
            }
        }
        dp.forEachIndexed { idx, arr -> arr.forEachIndexed { idy, _ -> dp[idx][idy] = next[idx][idy] } }
    }
    println(dp[half][0])
}
