    val st = StringTokenizer(br.readLine())
    val n = st.nextInt()
    val m = st.nextLong()
    val a = IntArray(n)
    val b = IntArray(n)
    val stA = StringTokenizer(br.readLine())
    for (i in 0 until n) a[i] = stA.nextInt()
    val stB = StringTokenizer(br.readLine())
    for (i in 0 until n) b[i] = stB.nextInt()

    val len = (n * m).toInt()
    val dp = Array(2) { LongArray(n + 1) { Long.MAX_VALUE / 2 } }
    dp[0][0] = 0

    for (i in 0 until len) {
        val cur = i % 2
        val next = 1 - cur
        for (j in 0..n) dp[next][j] = Long.MAX_VALUE / 2
        for (j in 0..n) {
            if (dp[cur][j] == Long.MAX_VALUE / 2) continue
            val costOpen = a[i % n]
            if (j + 1 <= n) {
                if (dp[cur][j] + costOpen < dp[next][j + 1]) {
                    dp[next][j + 1] = dp[cur][j] + costOpen
                }
            }
            val costClose = b[i % n]
            if (j > 0) {
                if (dp[cur][j] + costClose < dp[next][j - 1]) {
                    dp[next][j - 1] = dp[cur][j] + costClose
                }
            }
        }
    }

    println(dp[len % 2][0])
}
