import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val a = br.readLine().split(" ").map { it.toInt() }
    val b = br.readLine().split(" ").map { it.toInt() }

    val totalLength = n * m
    val half = totalLength / 2

    // dp[i][balance] = minimum cost up to i-th bracket with current balance
    // balance can be 0..half (since max balance is half)
    val dp = Array(totalLength + 1) { LongArray(half + 1) { Long.MAX_VALUE } }
    dp[0][0] = 0

    for (i in 0 until totalLength) {
        val idx = i % n
        for (bal in 0..half) {
            if (dp[i][bal] == Long.MAX_VALUE) continue
            // Place '('
            if (bal + 1 <= half) {
                val newCost = dp[i][bal] + a[idx]
                if (newCost < dp[i + 1][bal + 1]) {
                    dp[i + 1][bal + 1] = newCost
                }
            }
            // Place ')'
            if (bal > 0) {
                val newCost = dp[i][bal] + b[idx]
                if (newCost < dp[i + 1][bal - 1]) {
                    dp[i + 1][bal - 1] = newCost
                }
            }
        }
    }

    println(dp[totalLength][0])
}
