```kotlin
import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val a = br.readLine().split(" ").map { it.toInt() }
    val b = br.readLine().split(" ").map { it.toInt() }

    val total = n * m
    val half = total / 2

    // dp[i][j] = minimum cost to have processed i brackets with balance j
    // We use a rolling array to save memory
    val INF = Long.MAX_VALUE / 2
    var prevDp = Array(half + 1) { INF }
    prevDp[0] = 0

    for (i in 0 until total) {
        val currDp = Array(half + 1) { INF }
        val ai = a[i % n]
        val bi = b[i % n]
        for (j in 0..half) {
            if (prevDp[j] == INF) continue
            // Place '('
            if (j + 1 <= half) {
                currDp[j + 1] = minOf(currDp[j + 1], prevDp[j] + ai)
            }
            // Place ')'
            if (j > 0) {
                currDp[j - 1] = minOf(currDp[j - 1], prevDp[j] + bi)
            }
        }
        prevDp = currDp
    }

    println(prevDp[0])
}
