```kotlin
import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val a = br.readLine().split(" ").map { it.toInt() }
    val b = br.readLine().split(" ").map { it.toInt() }

    val total = n * m
    val half = total / 2

    // dp[i][balance] = min cost to process first i brackets with current balance
    // balance can be 0..i (but we can cap at n*m/2)
    // We use a rolling array to save memory
    val INF = Long.MAX_VALUE / 2
    val maxBalance = half
    var prev = Array(maxBalance + 1) { INF }
    prev[0] = 0

    for (i in 0 until total) {
        val curr = Array(maxBalance + 1) { INF }
        val ai = a[i % n]
        val bi = b[i % n]
        for (bal in 0..maxBalance) {
            if (prev[bal] == INF) continue
            // Place '('
            if (bal + 1 <= maxBalance) {
                val cost = prev[bal] + ai
                if (cost < curr[bal + 1]) {
                    curr[bal + 1] = cost
                }
            }
            // Place ')'
            if (bal > 0) {
                val cost = prev[bal] + bi
                if (cost < curr[bal - 1]) {
                    curr[bal - 1] = cost
                }
            }
        }
        prev = curr
    }

    println(prev[0])
}
